#pragma once
#include "test_harness.h"
#include "bigint_multiply_operand_view_cases.h"

namespace xlang3::test {
inline void check_bigint_division_working_buffers(CaseResult& result) {
  struct DivisionCase { const char* lhs; const char* rhs; const char* q; const char* r; };
  // Exact reference results generated by CPython 3.14.7. Cover sign adjustment,
  // multiword quotient bits, borrow chains, exact division and smaller dividend.
  const DivisionCase cases[] = {
    {"18446744073709551617", "129", "142998016075267841", "128"},
    {"18446744073709551617", "-129", "-142998016075267842", "-1"},
    {"-18446744073709551617", "129", "-142998016075267842", "1"},
    {"-18446744073709551617", "-129", "142998016075267841", "-128"},
    {"18446744073709551617", "18446744073709551617", "1", "0"},
    {"18446744073709551617", "-18446744073709551617", "-1", "0"},
    {"-18446744073709551617", "18446744073709551617", "-1", "0"},
    {"-18446744073709551617", "-18446744073709551617", "1", "0"},
    {"340282366920938463463374607431768211455", "18446744073709551617", "18446744073709551615", "0"},
    {"340282366920938463463374607431768211455", "-18446744073709551617", "-18446744073709551615", "0"},
    {"-340282366920938463463374607431768211455", "18446744073709551617", "-18446744073709551615", "0"},
    {"-340282366920938463463374607431768211455", "-18446744073709551617", "18446744073709551615", "0"},
    {"340282366920938463463374607431768211456", "4294967295", "79228162532711081671548469249", "1"},
    {"340282366920938463463374607431768211456", "-4294967295", "-79228162532711081671548469250", "-4294967294"},
    {"-340282366920938463463374607431768211456", "4294967295", "-79228162532711081671548469250", "4294967294"},
    {"-340282366920938463463374607431768211456", "-4294967295", "79228162532711081671548469249", "-1"},
    {"115792089237316195423570985008687907853269984665640564039457584007913129639935", "680564733841876926926749214863536422911", "170141183460469231731687303715884105728", "170141183460469231731687303715884105727"},
    {"115792089237316195423570985008687907853269984665640564039457584007913129639935", "-680564733841876926926749214863536422911", "-170141183460469231731687303715884105729", "-510423550381407695195061911147652317184"},
    {"-115792089237316195423570985008687907853269984665640564039457584007913129639935", "680564733841876926926749214863536422911", "-170141183460469231731687303715884105729", "510423550381407695195061911147652317184"},
    {"-115792089237316195423570985008687907853269984665640564039457584007913129639935", "-680564733841876926926749214863536422911", "170141183460469231731687303715884105728", "-170141183460469231731687303715884105727"},
    {"115792089237316195423570985008687907853269984665640564039457584007913129639937", "115792089237316195423570985008687907853269984665640564039457584007913129639973", "0", "115792089237316195423570985008687907853269984665640564039457584007913129639937"},
    {"115792089237316195423570985008687907853269984665640564039457584007913129639937", "-115792089237316195423570985008687907853269984665640564039457584007913129639973", "-1", "-36"},
    {"-115792089237316195423570985008687907853269984665640564039457584007913129639937", "115792089237316195423570985008687907853269984665640564039457584007913129639973", "-1", "36"},
    {"-115792089237316195423570985008687907853269984665640564039457584007913129639937", "-115792089237316195423570985008687907853269984665640564039457584007913129639973", "0", "-115792089237316195423570985008687907853269984665640564039457584007913129639937"},
    {"6277101735386680763495507056286727953321510367759519711212", "340282366920938463463374607431768211493", "18446744073709551615", "17"},
    {"6277101735386680763495507056286727953321510367759519711212", "-340282366920938463463374607431768211493", "-18446744073709551616", "-340282366920938463463374607431768211476"},
    {"-6277101735386680763495507056286727953321510367759519711212", "340282366920938463463374607431768211493", "-18446744073709551616", "340282366920938463463374607431768211476"},
    {"-6277101735386680763495507056286727953321510367759519711212", "-340282366920938463463374607431768211493", "18446744073709551615", "-17"},
    {"0", "340282366920938463463374607431768211493", "0", "0"},
    {"0", "-340282366920938463463374607431768211493", "0", "0"},
    {"0", "340282366920938463463374607431768211493", "0", "0"},
    {"0", "-340282366920938463463374607431768211493", "0", "0"},
    {"9223372036854775808", "1", "9223372036854775808", "0"},
    {"9223372036854775808", "-1", "-9223372036854775808", "0"},
    {"-9223372036854775808", "1", "-9223372036854775808", "0"},
    {"-9223372036854775808", "-1", "9223372036854775808", "0"},
  };
  std::string error;
  for (const auto& item : cases) {
    for (unsigned alias = 0; alias < 3; ++alias) {
      Value left = value_bigint_from_decimal(item.lhs, 10, error);
      Value right = value_bigint_from_decimal(item.rhs, 10, error);
      Value saved_left = left, saved_right = right;
      Value quotient, remainder;
      Value& q = alias == 1 ? left : alias == 2 ? right : quotient;
      Value& r = alias == 1 ? right : alias == 2 ? left : remainder;
      expect_true(result, value_int_like_divmod(left, right, q, r, error) &&
          value_to_string(q) == item.q && value_to_string(r) == item.r,
          "signed division results survive output aliases of either operand");
      expect_true(result, value_to_string(saved_left) == item.lhs &&
          value_to_string(saved_right) == item.rhs,
          "division working buffers must not mutate retained immutable inputs");
    }
  }
  Value left = value_bigint_from_decimal("18446744073709551617", 10, error);
  BigIntMultiplyReentryState state{&left};
  Value wrapper = Value::instance(Value::class_object("BigIntDivisionWrapper", {}));
  expect_true(result, instance_set_native_data(wrapper, "BigIntMultiplyReentry", &state, nullptr, error),
      "division conversion wrapper initializes");
  value_as_instance(wrapper)->native_get_attr = bigint_multiply_reentrant_wrapper;
  Value q, r;
  expect_true(result, value_int_like_divmod(left, wrapper, q, r, error) &&
      value_to_string(q) == "142998016075267841" && value_to_string(r) == "128" &&
      state.calls == 1 && left.as.i64 == 7,
      "division must retain converted left limbs across destructive right conversion");
  Value same = value_bigint_from_decimal("18446744073709551617", 10, error);
  expect_true(result, value_int_like_divmod(same, same, same, r, error) &&
      value_to_string(same) == "1" && value_to_string(r) == "0",
      "division allows one sole input owner shared by both operands and quotient");
  error.clear();
  expect_true(result, !value_int_like_divmod(Value::int64(5), Value::int64(0), q, r, error) &&
      error == "integer division or modulo by zero", "division by zero remains an arithmetic error");
}
} // namespace xlang3::test
